\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end $$;
create function pg_temp.assert_denied(statement text) returns void language plpgsql as $$ begin begin execute statement;exception when others then return;end;raise exception 'FAIL: statement was allowed: %',statement;end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select public.learning_command('{"type":"saveReportTemplate","template":{"id":"00000000-0000-4000-8000-000000000700","familyId":"00000000-0000-4000-8000-000000000700","name":"Проверочная работа","version":1,"scale":{"min":1,"max":5,"step":1},"areas":[{"id":"fractions","label":"Дроби","definition":"Работа по дробям","scope":"area","coverageConfirmed":false,"topicIds":["equivalent","add-fractions"]},{"id":"numbers","label":"Числа","definition":"Работа с числами","scope":"area","coverageConfirmed":false,"topicIds":["operations"]}]}}');
select public.learning_command('{"type":"saveReport","expectedRevision":0,"reason":"","report":{"id":"00000000-0000-4000-8000-000000000701","studentId":"00000000-0000-4000-8000-000000000001","templateId":"00000000-0000-4000-8000-000000000700","date":"2026-01-01","grade":4,"status":"draft","results":[{"areaId":"fractions","correct":0,"total":10},{"areaId":"numbers","correct":null,"total":null}]}}');
select pg_temp.assert_true((select payload->'results'->0->'correct'='0'::jsonb and payload->'results'->1->'correct'='null'::jsonb from public.teacher_reports),'zero and missing remain distinct');
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReportTemplate','template',(select content from public.report_templates limit 1)))$q$);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',1,'report',jsonb_set((select payload from public.teacher_reports limit 1),'{results,0,correct}','11'::jsonb)))$q$);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',1,'report',jsonb_set((select payload from public.teacher_reports limit 1),'{results,0,correct}','1.5'::jsonb)))$q$);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',1,'report',jsonb_set((select payload from public.teacher_reports limit 1),'{results,0,correct}','null'::jsonb)))$q$);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',1,'report',jsonb_set((select payload from public.teacher_reports limit 1),'{grade}','4.5'::jsonb)))$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from public.teacher_reports),'draft hidden from student');
select pg_temp.assert_true(jsonb_array_length(public.load_learning_state()->'reports')=0,'RPC draft hidden');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"readReport","reportId":"00000000-0000-4000-8000-000000000701","revision":1}')$q$);
select pg_temp.assert_denied($q$select public.learning_command_v3('{"type":"saveAssessment"}')$q$);
select pg_temp.assert_denied($q$select public.load_learning_state_v3()$q$);
select pg_temp.assert_denied($q$select public.learning_command('{"type":"saveReport"}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',1,'reason','','report',(select payload from public.teacher_reports limit 1)||'{"status":"published"}'::jsonb));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(jsonb_array_length(public.load_learning_state()->'reports')=1,'published reaches student');
select public.learning_command('{"type":"readReport","reportId":"00000000-0000-4000-8000-000000000701","revision":2}');
select pg_temp.assert_true((select revision=2 from public.report_reads),'seen revision recorded');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.teacher_reports),'other student cannot read');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"readReport","reportId":"00000000-0000-4000-8000-000000000701","revision":2}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_true(jsonb_array_length(public.load_learning_state()->'reports')=0,'unassigned teacher cannot read');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"saveReport","report":{"id":"00000000-0000-4000-8000-000000000701","studentId":"00000000-0000-4000-8000-000000000001"},"expectedRevision":2,"reason":"spoof"}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',2,'reason','','report',(select payload from public.teacher_reports limit 1)))$q$);
select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',2,'reason','Исправлена опечатка','report',jsonb_set((select payload from public.teacher_reports limit 1),'{results,0,correct}','6'::jsonb)));
select pg_temp.assert_true((select count(*)=1 and max(revision)=3 from public.teacher_reports),'correction replaces row');
select pg_temp.assert_true((select revision=2 from public.report_reads),'correction becomes unread');
select pg_temp.assert_true((select count(*)=3 from public.audit_events where entity_id='00000000-0000-4000-8000-000000000701'),'all revisions audited');
select pg_temp.assert_denied($q$select public.learning_command(jsonb_build_object('type','saveReport','expectedRevision',2,'reason','stale','report',(select payload from public.teacher_reports limit 1)))$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.learning_command('{"type":"requestDeletion","id":"00000000-0000-4000-8000-000000000702"}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.learning_command('{"type":"eraseStudent","studentId":"00000000-0000-4000-8000-000000000001"}');
select pg_temp.assert_true((select count(*)=0 from public.teacher_reports),'erasure cascades reports');
select pg_temp.assert_true((select count(*)=0 from public.report_reads),'erasure cascades receipts');
rollback;
\echo 'PASS: aggregate reports, validation, versions, corrections, read receipts, scoped permissions and erasure'
